def background(grid):
    """The most common color in the grid."""
    import collections
    return collections.Counter(v for row in grid for v in row).most_common(1)[0][0]

def accent(grid):
    """Every color in the grid other than the background."""
    return sorted({v for row in grid for v in row} - {background(grid)})

def recolor(grid, old, new):
    """The grid with every cell of color old recolored new."""
    return [[new if v == old else v for v in row] for row in grid]

def accent_to_zero_bg_to_accent(grid):
    """Every accent cell becomes 0 and every background cell takes the accent color."""
    bg = background(grid)
    acc = accent(grid)[0]
    return [[0 if v == acc else acc for v in row] for row in grid]

